def _get_ple_embedding_quant_method(
    quant_config: QuantizationConfig | None,
    prefix: str,
) -> QuantizeMethodBase | None:
    """Select global-scale FP8 only for quantized PLE checkpoint shards."""

    # sm_120 campaign: RadixArk's NVFP4 checkpoint ships FP8 PLE shards under a modelopt NVFP4 config that ignores
    # "*.ple.*"; force the FP8 PLE method when asked, whatever the quantization config says.
    import os as _os
    if _os.environ.get("VLLM_QWEN4EXP_PLE_FP8") == "1":
        return Qwen4ExpPLEFp8EmbeddingMethod()

    if isinstance(quant_config, ModelOptMixedPrecisionConfig):
        if quant_config._resolve_quant_algo(prefix) == "FP8":
            return Qwen4ExpPLEFp8EmbeddingMethod()
        return None

    if not isinstance(quant_config, Fp8Config):
        return None
    if not quant_config.is_checkpoint_fp8_serialized:
        return None

    ignored_layers = quant_config.ignored_layers
    if is_layer_skipped(
        prefix,
        ignored_layers,
        quant_config.packed_modules_mapping,
        match_mode=quant_config.ignored_layers_match_mode,
    ):
        return None
    # PLE checkpoint shards form one runtime embedding parameter.
    shard_prefix = f"{prefix}.shard_"
    if any(name.startswith(shard_prefix) for name in ignored_layers):
        return None
    return Qwen4ExpPLEFp8EmbeddingMethod()

